/**
 * How an ejected project's particles look and move (ADR 0080 D1, D4, D11), in
 * `<package>/client/particle/`: a copy of the runtime's `ParticleLook`
 * (`engine-mod/src/main/java/dev/mcsupermods/runtime/client/particle/`, Minecraft 26.3, Mojang
 * names), unchanged but for the package and comments. Pure: no Minecraft client type. The
 * generator's tests compare every code line with the runtime's.
 *
 * @packageDocumentation
 */

/** The source of `ParticleLook.java`, copied from the runtime's `ParticleLook`. */
export function particleLookJava(clientParticlePackage: string): string {
  return `// Generated by MCSuperMods: copied from msm_runtime's ParticleLook.
package ${clientParticlePackage};

import java.util.Locale;
import java.util.Objects;

/**
 * How a project particle looks and moves over its life (ADR 0080 D1, D4): the definition's knobs with their defaults
 * resolved ({@link Spec}) and pure functions of the particle's age. No Minecraft client types; MCSuperMods'
 * preview of a particle follows the same rules.
 *
 * <p>Ages are those {@link ModParticle} draws: 0 when created, then 1 up to the lifetime after each tick (the particle
 * is removed on the tick after it reaches its lifetime). The progress {@code t} through the life is
 * {@code age / lifetime}, clamped to 0..1 (plus the partial tick for the size).
 *
 * <p>The rules, written from ADR 0080 D1:
 * <ul>
 *   <li>Lifetime: a fixed number, or {@code min + floor(r × (max − min + 1))} for a random {@code r} in [0, 1),
 *       clamped to {@code min..max}.</li>
 *   <li>Frame: one texture always shows frame 0. {@code age}: {@code floor(age × frames / lifetime)}, at most the
 *       last frame (each frame shows for an equal share of the life). {@code loop}:
 *       {@code floor(age / frame_ticks) mod frames}. {@code random}: the frame picked when the particle is made.</li>
 *   <li>Size: from {@code size} to {@code size_end}, linear in {@code (age + partial) / lifetime}. It is vanilla's quad
 *       size: the quad is drawn from {@code −size} to {@code +size} around the centre, so it is {@code 2 × size}
 *       blocks wide.</li>
 *   <li>Colour: each channel ({@code 0xRRGGBB} over 255) linear from {@code color} to {@code color_end} in {@code t}.</li>
 *   <li>Alpha: {@code alpha} times the fade: {@code none} 1; {@code out} {@code 1 − t}; {@code in_out}
 *       {@code min(1, t / 0.25, (1 − t) / 0.25)} (in over the first quarter, out over the last).</li>
 *   <li>Roll: {@code spin × age} degrees, in radians (vanilla interpolates between the last two ticks' rolls).</li>
 *   <li>Movement of a particle that does not collide ({@link #step}): the vertical speed drops by
 *       {@code 0.04 × gravity}, the position moves by the speed, then every speed is multiplied by {@code friction};
 *       {@code gravity} and {@code friction} are single-precision numbers widened to double.</li>
 * </ul>
 */
public final class ParticleLook {
    /** Share of the life over which {@code in_out} fades in, and again out. */
    public static final float IN_OUT_EDGE = 0.25f;
    /** Vanilla's gravity step per tick per unit of {@code gravity}. */
    public static final double GRAVITY_STEP = 0.04;

    private ParticleLook() {
    }

    /** How a particle with more than one texture picks its frame. */
    public enum Animation {
        AGE, LOOP, RANDOM;

        public String serializedName() {
            return name().toLowerCase(Locale.ROOT);
        }

        /** The value for a definition's {@code animation}, or {@code null} for an unknown name. */
        public static Animation byName(String name) {
            for (Animation value : values()) {
                if (value.serializedName().equals(name)) {
                    return value;
                }
            }
            return null;
        }
    }

    /** How the alpha changes over the life. */
    public enum Fade {
        NONE, OUT, IN_OUT;

        public String serializedName() {
            return name().toLowerCase(Locale.ROOT);
        }

        /** The value for a definition's {@code fade}, or {@code null} for an unknown name. */
        public static Fade byName(String name) {
            for (Fade value : values()) {
                if (value.serializedName().equals(name)) {
                    return value;
                }
            }
            return null;
        }
    }

    /**
     * The knobs of ADR 0080 D1 with every default resolved. The pictures are not here: the client takes them from the
     * particle atlas through the particle's description. The canonical constructor checks D1's ranges and
     * {@code lifetimeMin <= lifetimeMax}; {@link #resolve} fills the defaults.
     */
    public record Spec(
            Animation animation,
            int frameTicks,
            int lifetimeMin,
            int lifetimeMax,
            float size,
            float sizeEnd,
            float gravity,
            float friction,
            boolean collision,
            int color,
            int colorEnd,
            float alpha,
            Fade fade,
            boolean emissive,
            boolean translucent,
            float spin,
            boolean alwaysShow) {
        /** A definition with only its textures. */
        public static final Spec DEFAULTS = resolve(null, null, null, null, null, null, null, null, null, null, null,
                null, null, null, null, null, null);

        public Spec {
            Objects.requireNonNull(animation, "animation");
            Objects.requireNonNull(fade, "fade");
            check(frameTicks >= 1 && frameTicks <= 1200, "frame_ticks", frameTicks);
            check(lifetimeMin >= 1 && lifetimeMin <= 6000, "lifetime min", lifetimeMin);
            check(lifetimeMax >= 1 && lifetimeMax <= 6000, "lifetime max", lifetimeMax);
            check(lifetimeMin <= lifetimeMax, "lifetime min above max", lifetimeMin);
            check(size >= 0.01f && size <= 16f, "size", size);
            check(sizeEnd >= 0f && sizeEnd <= 16f, "size_end", sizeEnd);
            check(gravity >= -16f && gravity <= 16f, "gravity", gravity);
            check(friction >= 0f && friction <= 1f, "friction", friction);
            check(color >= 0 && color <= 0xFFFFFF, "color", color);
            check(colorEnd >= 0 && colorEnd <= 0xFFFFFF, "color_end", colorEnd);
            check(alpha >= 0f && alpha <= 1f, "alpha", alpha);
            check(spin >= -360f && spin <= 360f, "spin", spin);
        }

        private static void check(boolean ok, String field, Object value) {
            if (!ok) {
                throw new IllegalArgumentException("particle " + field + " out of range: " + value);
            }
        }

        /**
         * The spec of a definition whose absent fields are {@code null}: {@code animation} {@code age},
         * {@code frame_ticks} 2, {@code lifetime} 20 (a fixed lifetime gives the same min and max), {@code size} 0.2,
         * {@code size_end} = size, {@code gravity} 0, {@code friction} 0.98, {@code collision} true, {@code color}
         * white, {@code color_end} = color, {@code alpha} 1, {@code fade} {@code none}, {@code emissive} false,
         * {@code translucent} true when alpha is below 1 or fade is not {@code none}, {@code spin} 0,
         * {@code always_show} false. The generated client entrypoint builds each type's spec through this method.
         */
        public static Spec resolve(
                Animation animation,
                Integer frameTicks,
                Integer lifetimeMin,
                Integer lifetimeMax,
                Float size,
                Float sizeEnd,
                Float gravity,
                Float friction,
                Boolean collision,
                Integer color,
                Integer colorEnd,
                Float alpha,
                Fade fade,
                Boolean emissive,
                Boolean translucent,
                Float spin,
                Boolean alwaysShow) {
            float resolvedSize = size != null ? size : 0.2f;
            int resolvedColor = color != null ? color : 0xFFFFFF;
            float resolvedAlpha = alpha != null ? alpha : 1f;
            Fade resolvedFade = fade != null ? fade : Fade.NONE;
            int min = lifetimeMin != null ? lifetimeMin : 20;
            int max = lifetimeMax != null ? lifetimeMax : min;
            return new Spec(
                    animation != null ? animation : Animation.AGE,
                    frameTicks != null ? frameTicks : 2,
                    min,
                    max,
                    resolvedSize,
                    sizeEnd != null ? sizeEnd : resolvedSize,
                    gravity != null ? gravity : 0f,
                    friction != null ? friction : 0.98f,
                    collision != null ? collision : true,
                    resolvedColor,
                    colorEnd != null ? colorEnd : resolvedColor,
                    resolvedAlpha,
                    resolvedFade,
                    emissive != null && emissive,
                    translucent != null ? translucent : resolvedAlpha < 1f || resolvedFade != Fade.NONE,
                    spin != null ? spin : 0f,
                    alwaysShow != null && alwaysShow);
        }
    }

    /** Colour and alpha, each 0 to 1. */
    public record Rgba(float r, float g, float b, float a) {
    }

    /** Position and speed (blocks, blocks per tick) of a particle that does not collide. */
    public record State(double x, double y, double z, double xd, double yd, double zd) {
    }

    /** The lifetime from {@code min} to {@code max} for a random {@code r} in [0, 1). */
    public static int lifetime(int min, int max, double r) {
        int value = min + (int) Math.floor(r * (max - min + 1));
        return Math.max(min, Math.min(max, value));
    }

    /** The progress through the life, 0 to 1. */
    public static float progress(int age, float partial, int lifetime) {
        float t = (age + partial) / (float) Math.max(1, lifetime);
        return Math.max(0f, Math.min(1f, t));
    }

    /**
     * The frame index, 0 to {@code frames − 1}; {@code randomFrame} is the frame picked when the particle was made
     * (used by {@code random} only).
     */
    public static int frame(Spec spec, int age, int lifetime, int frames, int randomFrame) {
        if (frames <= 1) {
            return 0;
        }
        int a = Math.max(0, age);
        return switch (spec.animation()) {
            case AGE -> (int) Math.min(frames - 1L, (long) a * frames / Math.max(1, lifetime));
            case LOOP -> (a / spec.frameTicks()) % frames;
            case RANDOM -> Math.floorMod(randomFrame, frames);
        };
    }

    /** The quad size (half the drawn width) at {@code age} plus the partial tick. */
    public static float size(Spec spec, int age, int lifetime, float partial) {
        float t = progress(age, partial, lifetime);
        return spec.size() + (spec.sizeEnd() - spec.size()) * t;
    }

    /** The colour and alpha at {@code age}. */
    public static Rgba rgba(Spec spec, int age, int lifetime) {
        float t = progress(age, 0f, lifetime);
        float fade = switch (spec.fade()) {
            case NONE -> 1f;
            case OUT -> 1f - t;
            case IN_OUT -> Math.max(0f, Math.min(1f, Math.min(t / IN_OUT_EDGE, (1f - t) / IN_OUT_EDGE)));
        };
        return new Rgba(
                channel(spec.color(), spec.colorEnd(), 16, t),
                channel(spec.color(), spec.colorEnd(), 8, t),
                channel(spec.color(), spec.colorEnd(), 0, t),
                spec.alpha() * fade);
    }

    private static float channel(int from, int to, int shift, float t) {
        float a = ((from >> shift) & 0xFF) / 255f;
        float b = ((to >> shift) & 0xFF) / 255f;
        return a + (b - a) * t;
    }

    /** The roll in radians at {@code age}. */
    public static float roll(Spec spec, int age) {
        return (float) Math.toRadians((double) spec.spin() * age);
    }

    /** Whether the particle is drawn in the translucent layer (else cut-out). */
    public static boolean translucent(Spec spec) {
        return spec.translucent();
    }

    /** One tick of movement for a particle that does not collide. */
    public static State step(State state, Spec spec) {
        double friction = spec.friction();
        double yd = state.yd() - GRAVITY_STEP * (double) spec.gravity();
        double x = state.x() + state.xd();
        double y = state.y() + yd;
        double z = state.z() + state.zd();
        return new State(x, y, z, state.xd() * friction, yd * friction, state.zd() * friction);
    }
}
`;
}
